SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS benchmark_runs (
    id                       INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    run_id                   VARCHAR(64) NOT NULL UNIQUE,
    label                    VARCHAR(128),
    status                   ENUM('pending','running','completed','failed','canceled') DEFAULT 'pending',
    dataset_snapshot         JSON,
    dataset_hash             VARCHAR(64),
    pipeline_version         VARCHAR(64),
    config_hash              VARCHAR(64),
    code_version             VARCHAR(64),
    warmup_excluded_count    INT NOT NULL DEFAULT 0,
    total_items              INT NOT NULL DEFAULT 0,
    processed_items          INT NOT NULL DEFAULT 0,
    failed_items             INT NOT NULL DEFAULT 0,
    p50_runtime_sec          FLOAT,
    p95_runtime_sec          FLOAT,
    avg_runtime_sec          FLOAT,
    failure_rate             FLOAT,
    fallback_rate            FLOAT,
    stage_runtime_totals     JSON,
    data_health_summary      JSON,
    error_message            TEXT,
    created_at               DATETIME DEFAULT CURRENT_TIMESTAMP,
    started_at               DATETIME,
    completed_at             DATETIME,
    updated_at               DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_benchmark_runs_created_at (created_at),
    INDEX idx_benchmark_runs_status (status),
    INDEX idx_benchmark_runs_dataset_hash (dataset_hash)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS benchmark_run_items (
    id                       INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    benchmark_run_id         INT UNSIGNED NOT NULL,
    submission_id            INT UNSIGNED NULL,
    sample_index             INT NOT NULL,
    is_warmup                TINYINT(1) NOT NULL DEFAULT 0,
    status                   ENUM('pending','running','completed','failed','skipped') DEFAULT 'pending',
    metric_snapshot          JSON,
    runtime_sec              FLOAT,
    error_message            TEXT,
    embedding_backend        VARCHAR(16),
    pipeline_steps           JSON,
    created_at               DATETIME DEFAULT CURRENT_TIMESTAMP,
    started_at               DATETIME,
    completed_at             DATETIME,
    FOREIGN KEY (benchmark_run_id) REFERENCES benchmark_runs(id) ON DELETE CASCADE,
    FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE SET NULL,
    UNIQUE KEY uq_benchmark_run_item_index (benchmark_run_id, sample_index),
    UNIQUE KEY uq_benchmark_run_item_submission (benchmark_run_id, submission_id),
    INDEX idx_benchmark_run_items_status (status),
    INDEX idx_benchmark_run_items_submission_id (submission_id)
) ENGINE=InnoDB;

START TRANSACTION;
DELETE bri FROM benchmark_run_items bri JOIN benchmark_runs br ON br.id = bri.benchmark_run_id WHERE br.run_id IN ('BENCH-20260527-151525-e4eec79a','BENCH-20260527-152044-37f01d75');
DELETE FROM benchmark_runs WHERE run_id IN ('BENCH-20260527-151525-e4eec79a','BENCH-20260527-152044-37f01d75');
SET @baseline_run_db_id = LAST_INSERT_ID();
SET @optimized_run_db_id = LAST_INSERT_ID();
COMMIT;
SELECT run_id,label,total_items,processed_items,p50_runtime_sec,p95_runtime_sec,avg_runtime_sec FROM benchmark_runs WHERE run_id IN ('BENCH-20260527-151525-e4eec79a','BENCH-20260527-152044-37f01d75') ORDER BY run_id;
SELECT br.run_id, COUNT(*) AS item_count FROM benchmark_runs br JOIN benchmark_run_items bri ON bri.benchmark_run_id = br.id WHERE br.run_id IN ('BENCH-20260527-151525-e4eec79a','BENCH-20260527-152044-37f01d75') GROUP BY br.run_id ORDER BY br.run_id;
